import React, { useState, useEffect, useCallback, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { 
  Shuffle, 
  ArrowLeftRight, 
  Download, 
  FileSpreadsheet, 
  FileText, 
  Upload, 
  RefreshCcw,
  Sparkles,
  Info,
  FileDown,
  Lock
} from 'lucide-react';
import { Student, Seat, Gender } from './types';
import { ROWS, COLS, DEFAULT_STUDENTS } from './constants';
import SeatCard from './components/SeatCard';
import { analyzeSeating } from './services/geminiService';

const App: React.FC = () => {
  const [students, setStudents] = useState<Student[]>(DEFAULT_STUDENTS);
  const [seats, setSeats] = useState<Seat[]>([]);
  const [selectedSeatIndex, setSelectedSeatIndex] = useState<number | null>(null);
  const [aiAdvice, setAiAdvice] = useState<string>("");
  const [isLoadingAi, setIsLoadingAi] = useState(false);
  const [swapIds, setSwapIds] = useState({ id1: '', id2: '' });

  // 初期配置
  const initializeSeats = useCallback((studentList: Student[]) => {
    const newSeats: Seat[] = [];
    let studentIndex = 0;
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        newSeats.push({
          row: r,
          col: c,
          student: studentList[studentIndex] || null,
          isLocked: false // 初期値は未固定
        });
        studentIndex++;
      }
    }
    setSeats(newSeats);
  }, []);

  useEffect(() => {
    initializeSeats(students);
  }, [initializeSeats]);

  // シャッフル（固定された座席は動かさない）
  const handleShuffle = () => {
    const unlockedIndices = seats.reduce((acc, seat, idx) => {
      if (!seat.isLocked) acc.push(idx);
      return acc;
    }, [] as number[]);

    if (unlockedIndices.length === 0) {
