            <button 
              onClick={exportPDF}
              className="flex-1 flex items-center justify-center gap-2 bg-rose-600 hover:bg-rose-700 text-white py-3 rounded-xl font-bold transition-all shadow-sm"
            >
              <FileText size={20} />
              座席表PDF出力
            </button>
          </div>
        </div>
      </main>
    </div>
  );
};

