            </h2>
            <div className="space-y-3">
              <input 
                type="text" placeholder="学籍番号1" value={swapIds.id1}
                onChange={(e) => setSwapIds({...swapIds, id1: e.target.value})}
                className="w-full px-4 py-3 text-xs border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all"
              />
              <input 
