                <div className="flex items-center gap-3 text-[10px] font-black text-rose-600 bg-rose-50/50 px-6 py-3 rounded-2xl border border-rose-100/50 shadow-sm">
                  <Ban size={14}/> 座席を使用不可に
                </div>
                <div className="flex items-center gap-3 text-[10px] font-black text-slate-400 bg-slate-50 px-6 py-3 rounded-2xl border border-slate-200/50 shadow-sm">
                  <Info size={14}/> 空席は後方へ自動集約
                </div>
              </div>

              <div className="flex items-center gap-6">
                <div className="text-[11px] font-black text-slate-500 bg-slate-100 px-8 py-4 rounded-[1.5rem] border border-slate-200 flex items-center gap-3 shadow-inner">
                  <CheckCircle2 size={16} className="text-emerald-500" />
