import React from 'react';
import { Student } from '../types';
import { User, UserCheck, Lock, Unlock, Ban } from 'lucide-react';

interface SeatCardProps {
  student: Student | null;
  isSelected: boolean;
  isLocked: boolean;
  isUnusable: boolean;
  onClick: () => void;
  onToggleLock: (e: React.MouseEvent) => void;
  onToggleUnusable: (e: React.MouseEvent) => void;
  row: number;
  col: number;
}

const SeatCard: React.FC<SeatCardProps> = ({ 
  student, 
  isSelected, 
  isLocked, 
  isUnusable,
  onClick, 
  onToggleLock, 
  onToggleUnusable,
  row, 
  col 
}) => {
  return (
    <div
      onClick={isUnusable ? undefined : onClick}
      className={`
        relative flex flex-col items-center justify-center p-1 sm:p-2 rounded-lg border-2 transition-all h-20 sm:h-24 w-full
        ${isUnusable 
          ? 'bg-slate-200 border-slate-300 opacity-80 cursor-default' 
          : isLocked 
            ? 'bg-indigo-50/50 border-indigo-300 cursor-pointer' 
            : 'bg-white border-slate-200 cursor-pointer'}
        ${!isUnusable && student 
          ? (isSelected ? 'border-blue-500 bg-blue-50 shadow-md scale-105 z-10' : 'hover:border-blue-300 hover:shadow-sm') 
          : (!isUnusable ? 'border-dashed border-slate-300 bg-slate-50 opacity-60 hover:opacity-100' : '')}
      `}
    >
      <div className="absolute top-0.5 left-1 text-[8px] sm:text-[10px] text-slate-400 font-mono">
        R{row+1}C{col+1}
      </div>

      <div className="absolute top-0.5 right-0.5 flex gap-0.5">
        <button
          onClick={onToggleUnusable}
          className={`
            p-0.5 sm:p-1 rounded-md transition-colors
            ${isUnusable ? 'text-red-600 bg-red-100' : 'text-slate-300 hover:text-red-400 hover:bg-red-50'}
          `}
        >
          <Ban size={10} className="sm:w-[12px] sm:h-[12px]" />
        </button>

        {!isUnusable && (
          <button
            onClick={onToggleLock}
            className={`
              p-0.5 sm:p-1 rounded-md transition-colors
              ${isLocked ? 'text-indigo-600 bg-indigo-100' : 'text-slate-300 hover:text-indigo-400 hover:bg-indigo-50'}
            `}
          >
            {isLocked ? <Lock size={10} className="sm:w-[12px] sm:h-[12px]" /> : <Unlock size={10} className="sm:w-[12px] sm:h-[12px]" />}
          </button>
        )}
      </div>

      {isUnusable ? (
        <div className="flex flex-col items-center justify-center opacity-40">
          <Ban size={16} className="text-slate-500 mb-0.5 sm:mb-1 sm:w-[20px] sm:h-[20px]" />
          <div className="text-[8px] sm:text-[10px] font-bold text-slate-500 uppercase tracking-tighter">不可</div>
        </div>
      ) : student ? (
        <>
          <div className={`p-0.5 sm:p-1 rounded-full mb-0.5 sm:mb-1 ${student.gender === '男' ? 'bg-blue-100 text-blue-600' : 'bg-rose-100 text-rose-600'}`}>
            <User size={12} className="sm:w-[16px] sm:h-[16px]" />
          </div>
          <div className="text-[10px] sm:text-xs font-bold truncate max-w-full leading-tight">{student.name}</div>
          <div className="text-[8px] sm:text-[10px] text-slate-500">{student.id}</div>
          <div className="hidden sm:block text-[9px] px-1 bg-slate-100 rounded mt-0.5 truncate max-w-full">{student.subject}</div>
        </>
      ) : (
        <div className="text-[10px] sm:text-xs text-slate-400 font-medium italic">空席</div>
      )}

      {isSelected && !isLocked && !isUnusable && (
        <div className="absolute bottom-0.5 right-0.5">
          <div className="bg-blue-500 text-white rounded-full p-0.5">
            <UserCheck size={8} className="sm:w-[12px] sm:h-[12px]" />
          </div>
        </div>
      )}
    </div>
  );
};

export default SeatCard;

import React, { useState, useEffect, useCallback } from 'react';
import * as XLSX from 'xlsx';
import { 
  Shuffle, 
  ArrowLeftRight, 
  FileSpreadsheet, 
  Upload, 
  RefreshCcw,
  Info,
  FileDown,
  Lock,
  Ban,
  ShieldCheck,
  EyeOff,
  CheckCircle2,
  HardDriveDownload,
  ServerOff,
  Layout
} from 'lucide-react';
import { Student, Seat, Gender } from './types';
import { ROWS, COLS, DEFAULT_STUDENTS } from './constants';
import SeatCard from './components/SeatCard';

const App: React.FC = () => {
  const [students, setStudents] = useState<Student[]>(DEFAULT_STUDENTS);
  const [seats, setSeats] = useState<Seat[]>([]);
  const [selectedSeatIndex, setSelectedSeatIndex] = useState<number | null>(null);
  const [swapIds, setSwapIds] = useState({ id1: '', id2: '' });
  const [isProcessing, setIsProcessing] = useState(false);

  /**
   * 座席の初期化
   * 空席を教室後方（画面上部）に配置するロジック
   */
  const initializeSeats = useCallback((studentList: Student[]) => {
    const totalSeatsCount = ROWS * COLS;
    const newSeats: Seat[] = [];

    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        newSeats.push({
          row: r,
          col: c,
          student: null,
          isLocked: false,
          isUnusable: false
        });
      }
    }

    const reversedIndices = Array.from({ length: totalSeatsCount }, (_, i) => i).reverse();

    studentList.forEach((student, i) => {
      if (i < totalSeatsCount) {
        newSeats[reversedIndices[i]].student = student;
      }
    });

    setSeats(newSeats);
  }, []);

  useEffect(() => {
    initializeSeats(students);
  }, [initializeSeats]);

  const handleShuffle = () => {
    if (students.length === 0) {
      alert("名簿をインポートしてから実行してください。");
      return;
    }

    setIsProcessing(true);

    setTimeout(() => {
      const targetIndices = seats.reduce((acc, seat, idx) => {
        if (!seat.isLocked && !seat.isUnusable) acc.push(idx);
        return acc;
      }, [] as number[]);

      const studentsInPlay = seats
        .filter((_, idx) => targetIndices.includes(idx))
        .map(s => s.student)
        .filter((s): s is Student => s !== null);

      if (targetIndices.length < studentsInPlay.length) {
        alert("有効な座席数が不足しています。座席設定を見直してください。");
        setIsProcessing(false);
        return;
      }

      const shuffledStudents = [...studentsInPlay].sort(() => Math.random() - 0.5);
      const newSeats = [...seats];

      targetIndices.forEach(idx => {
        newSeats[idx].student = null;
      });

      const fillIndices = [...targetIndices].sort((a, b) => b - a);

      shuffledStudents.forEach((student, i) => {
        const seatIdx = fillIndices[i];
        newSeats[seatIdx].student = student;
      });

      setSeats(newSeats);
      setSelectedSeatIndex(null);
      setIsProcessing(false);
    }, 500); 
  };

  const handleToggleLock = (index: number, e: React.MouseEvent) => {
    e.stopPropagation();
    if (seats[index].isUnusable) return;
    const newSeats = [...seats];
    newSeats[index].isLocked = !newSeats[index].isLocked;
    setSeats(newSeats);
    if (selectedSeatIndex === index) setSelectedSeatIndex(null);
  };

  const handleToggleUnusable = (index: number, e: React.MouseEvent) => {
    e.stopPropagation();
    const newSeats = [...seats];
    const targetSeat = newSeats[index];
    if (!targetSeat.isUnusable) {
      targetSeat.isLocked = false;
      targetSeat.student = null;
    }
    targetSeat.isUnusable = !targetSeat.isUnusable;
    setSeats(newSeats);
    if (selectedSeatIndex === index) setSelectedSeatIndex(null);
  };

  const handleSeatClick = (index: number) => {
    if (seats[index].isLocked || seats[index].isUnusable) return;
    if (selectedSeatIndex === null) {
      if (seats[index].student) setSelectedSeatIndex(index);
    } else {
      const newSeats = [...seats];
      const temp = newSeats[selectedSeatIndex].student;
      newSeats[selectedSeatIndex].student = newSeats[index].student;
      newSeats[index].student = temp;
      setSeats(newSeats);
      setSelectedSeatIndex(null);
    }
  };

  const handleManualSwap = () => {
    const { id1, id2 } = swapIds;
    if (!id1 || !id2) return;
    const idx1 = seats.findIndex(s => s.student?.id === id1);
    const idx2 = seats.findIndex(s => s.student?.id === id2);
    if (idx1 === -1 || idx2 === -1) {
      alert("該当する生徒が見つかりません。");
      return;
    }
    const newSeats = [...seats];
    const temp = newSeats[idx1].student;
    newSeats[idx1].student = newSeats[idx2].student;
    newSeats[idx2].student = temp;
    setSeats(newSeats);
    setSwapIds({ id1: '', id2: '' });
  };

  const downloadTemplate = () => {
    const data = [
      { "学籍番号": "1001", "名前": "佐藤 健一", "選択科目": "物理", "性別": "男" },
      { "学籍番号": "1002", "名前": "田中 美咲", "選択科目": "生物", "性別": "女" }
    ];
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Template");
    XLSX.writeFile(wb, "名簿テンプレート.xlsx");
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = (evt) => {
      const data = evt.target?.result;
      const workbook = XLSX.read(data, { type: 'binary' });
      const sheet = workbook.Sheets[workbook.SheetNames[0]];
      const json = XLSX.utils.sheet_to_json(sheet) as any[];
      const imported = json.map((row: any) => ({
        id: String(row['学籍番号'] || row['id'] || ''),
        name: String(row['名前'] || row['name'] || '不明'),
        subject: String(row['選択科目'] || row['subject'] || ''),
        gender: ((row['性別'] === '女' || row['gender'] === 'female') ? '女' : '男') as Gender
      })).filter(s => s.id);
      setStudents(imported);
      initializeSeats(imported);
      setIsProcessing(false);
    };
    reader.readAsBinaryString(file);
  };

  const exportExcel = () => {
    const tableData = [];
    const header = [];
    for (let c = 0; c < COLS; c++) header.push(`${c + 1}列目`);
    tableData.push(header);

    for (let r = 0; r < ROWS; r++) {
      const rowArr = [];
      for (let c = 0; c < COLS; c++) {
        const seat = seats.find(s => s.row === r && s.col === c);
        if (seat?.isUnusable) {
          rowArr.push("使用不可");
        } else if (seat?.student) {
          rowArr.push(`${seat.student.name} (${seat.student.id})`);
        } else {
          rowArr.push("(空席)");
        }
      }
      tableData.push(rowArr);
    }

    const ws = XLSX.utils.aoa_to_sheet(tableData);
    ws['!cols'] = Array(COLS).fill({ wch: 25 });
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "座席表");
    XLSX.writeFile(wb, "座席表_出力.xlsx");
  };

  return (
