            {/* Seating Grid */}
            <div className="flex-1 overflow-x-auto sm:overflow-visible">
              <div className="grid grid-cols-6 gap-2 sm:gap-6 xl:gap-8 min-w-[450px] sm:min-w-0">
                {seats.map((seat, index) => (
                  <SeatCard
                    key={index}
